#include <stdio.h>
#include <stdlib.h>

typedef long long ll;
typedef unsigned long long ull;
typedef __int128 lll;

static char ibuf[1 << 22];
static size_t ipos = 0, ilen = 0;

static inline int gc(void) {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return (unsigned char)ibuf[ipos++];
}

static ll readLL(void) {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9') && c != '-') c = gc();
    int neg = 0;
    if (c == '-') { neg = 1; c = gc(); }
    ll x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = gc();
    }
    return neg ? -x : x;
}

static char obuf[1 << 20];
static size_t opos = 0;

static void writeULL(ull v) {
    char tmp[24];
    int t = 0;
    do { tmp[t++] = (char)('0' + (v % 10)); v /= 10; } while (v);
    while (t) obuf[opos++] = tmp[--t];
    obuf[opos++] = '\n';
}

int main(void) {
    ll P = readLL();
    while (P-- > 0) {
        ll L = readLL(), A = readLL(), B = readLL();
        ull n = (ull)B - (ull)A + 1ULL;
        lll T = ((lll)n * (lll)(A + B)) / 2;
        ull ans;
        if (T < (lll)L) {
            /* Soma total de todos os valores disponiveis nao alcanca L:
               Joao joga todas as n rodadas sem cruzar o limite. */
            ans = n;
        } else {
            /* A soma apos j rodadas e sempre >= f(j) = j*A + j*(j-1)/2
               (soma dos j menores valores do intervalo).
               Logo o jogo acaba em ate m1+1 rodadas, onde m1 e o maior m
               com f(m) < L. Jogando A, A+1, ..., A+m1 em ordem crescente,
               as prefixadas ficam < L e ele completa exatamente m1+1 rodadas. */
            ull m1 = 0;
            if (n >= 2ULL) {
                ull lo = 1ULL, hi = n - 1ULL;
                while (lo <= hi) {
                    ull mid = lo + (hi - lo) / 2ULL;
                    lll fm = (lll)mid * (lll)A + ((lll)mid * (lll)(mid - 1ULL)) / 2;
                    if (fm < (lll)L) { m1 = mid; lo = mid + 1ULL; }
                    else hi = mid - 1ULL;
                }
            }
            ans = m1 + 1ULL;
        }
        writeULL(ans);
    }
    fwrite(obuf, 1, opos, stdout);
    return 0;
}
